@@ -0,0 +1,7 @@
+use trussbars_macros::truss;
+
+// Arity-class: a fixed-arity stdlib op called with the wrong number of arguments
+// (`uppercase` takes one). Rejected before codegen with a located, owned message.
+truss!(render, str, "{{uppercase a b}}");
+
+fn main() {}

@@ -0,0 +1,6 @@
+use trussbars_macros::truss;
+
+// Dict-literal-class: a `{k: v}` literal cannot be iterated; bind and read fields.
+truss!(render, str, "{{#each {a: 1}}}{{this}}{{/each}}");
+
+fn main() {}

@@ -0,0 +1,6 @@
+use trussbars_macros::truss;
+
+// Loop-metadata-class: `loop` is only bound inside an `{{#each}}`.
+truss!(render, str, "{{loop.index0}}");
+
+fn main() {}

@@ -0,0 +1,6 @@
+use trussbars_macros::truss;
+
+// Loop-metadata-class: an unknown field on the loop frame.
+truss!(render, str, "{{#each items}}{{loop.bogus}}{{/each}}");
+
+fn main() {}
